# owner: platform
"""Plain-text absence notices for parents."""

from typing import Iterable

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.attendance import days_missed

def check_owner(student: Student, marks: list) -> None:
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ProjectError(
                f"mark for {mark.student_id!r} is not "
                f"for {student.student_id!r}"
            )

def heading(student: Student, count: int) -> str:
    """First line: who, and how many days."""
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {count} {noun} of school:"

def format_notice(student: Student, days: list) -> str:
    """Lay out the notice text for sorted days."""
    lines = [heading(student, len(days))]
    lines += [f"  - {when.isoformat()}" for when in days]
    return "\n".join(lines)

def build_notice(student: Student, marks: Iterable) -> str:
    """Short notice naming the student and absent days."""
    marks = list(marks)
    check_owner(student, marks)
    days = days_missed(marks)
    if not days:
        raise ProjectError("no absences to write about")
    return format_notice(student, days)
